static inline const uint16_t* getEndlessDuelSprite(int stage, int pose, int frame) {
  if (stage < 0 || stage > 2) stage = 0;
  if (pose < 0 || pose > 2) pose = 0;
  return ED_FRAME_TABLE[stage][pose][frame & 7];
}

